  FT["PH-H2186"] = {"id":"PH-H2186","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2456_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Establishment of a Branch Hospital of the Cagayan Provincial Hospital in the Municipality of Piat, Province of Cagayan, to be Known as the Itawes Provincial Hospital and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Branch Hospital of the Cagayan Provincial Hospital in the Municipality of Piat, Province of Cagayan, to be Known as the Itawes Provincial Hospital and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2456","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2456_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2186-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Medical Services, a branch hospital of the Cagayan Provincial Hospital in the Municipality of Piat, Province of Cagayan, to be known as the Itawes Provincial Hospital."}},{"id":"PH-H2186-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Health shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H2186-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital."}},{"id":"PH-H2186-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
