  FT["PH-H2195"] = {"id":"PH-H2195","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2465_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Sta市","en":"An Act Creating the Barrios of Salvacion, Roxas, Sundra, Solosogon, Bahay, Bana-Ao, Agrupacion, Arapison, Victory, Caasloman, Barabod, Nabulo, Mahayag, Inoragyao, Mabuhay, Lambao, Moroporo, Campeig, Canipulan, Gajo, Panaro-An, Perito, Palale and Caganahao in the Municipality of Sta. Margarita, Province of Samar","orig":"An Act Creating the Barrios of Salvacion, Roxas, Sundra, Solosogon, Bahay, Bana-Ao, Agrupacion, Arapison, Victory, Caasloman, Barabod, Nabulo, Mahayag, Inoragyao, Mabuhay, Lambao, Moroporo, Campeig, Canipulan, Gajo, Panaro-An, Perito, Palale and Caganahao in the Municipality of Sta. Margarita, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2465","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2465_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2195-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Sta. Margarita, Province of Samar:\n(1) Barrio Salvacion, consisting of the sitios of Hemaangno, Tina, Kinabugsohan Pana-awan, and Bungnog;\n(2) Barrio Roxas, consisting of the sitio of Panogoran, Misikpisik and Cadigamhon;\n(3) Barrio Sundra, consisting of the sitios of Naporo and Pasig;\n(4) Barrio Solsogon, consisting of the sitios of Cagbatilisan, Da-o, Cagsumhi, Calirangan, Nabura-West, Tigdaraja, Canmeriu and Mahabol;\n(5) Barrio Bahay, consisting of the sitios of Panlulogayan, Canhurao, Pamamaliwan and Minorosan;\n(6) Barrio Bana-ao, consisting of the sitios of Laboyao, Macatol, Cabariwan, Sinagoksokan, Kinarangdangan and Pasongon;\n(7) Barrio Agrupacion, consisting of the sitio of Anoling;\n(8) Barrio Arapison, consisting of the sitios of Bangon, Illawod, Guincatol-an Magcahibang and Campagote;\n(9) Barrio Victory, consisting of the sitios of Hinaango, Lotang, Canati-an, Logos, Macalayalaya, Cahanagdongan and Ombo-bo;\n(10) Barrio Caasloman, consisting of the sitios of Heogba, Natopo, Capudlosan, Cabacongan and Tibobnot;\n(11) Barrio Burabod, consisting of the sitios of Caglagting, Epil, Malicolico and Canloncas;\n(12) Barrio Nabulo, consisting of the sitios of Tibalad, Napuliron, Dalakit, Canamailon and Bakung;\n(13) Barrio Mahayag, consisting of the sitios of Aliat, Pangalaw-an, Panihwan, Capantapan, Hecaloty, Maloyapayo, Barrayong and Cabatuan;\n(14) Barrio Inoragyao, consisting of the sitios of Guin haran, Nabulo-Sur, Agusip, Canmalon, Pinamaliwan and Capinyahan;\n(15) Barrio Mabuhay, consisting of the sitios of Can Tomas, Mueblo, Castillano and Cangkokong;\n(16) Barrio Lambao, consisting of the sitios of Da-o, Nabora and Restituloriwa;\n(17) Barrio Moroporo, consisting of the sitios of Lininiti-an and Magcayongod;\n(18) Barrio Campeig, consisting of the sitios of Canba-nog, Sosocon, Alao and Felehan;\n(19) Barrio Canipulan, consisting of the sitios of Cantimbang, Cancappilong and Cangodio;\n(20) Barrio Gajo, consisting of the sitios of Malolonod, Guinbologo-an Canbanog and Biad;\n(21) Barrio Panaro-an consisting of the sitio of Kinabogsocan, Cambanog and Caninaria;\n(22) Barrio Perito, consisting of the sitios of Tinbobonot, Honoapan and Caboago-an;\n(23) Barrio Palale, consisting of the sitios of Magdodilot, Saquib, Guinsohayan, Pangpang, Lobtong and Cataynazan; and\n(24) Barrio Caganahao, consisting of the sitios of Pangogob-an, Lumaras and Hindang."}},{"id":"PH-H2195-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2196"] = {"id":"PH-H2196","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2466_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Calbayog市","en":"An Act Creating the Barrios of Kilikili, Acedillo, Dagum, Tomaleguis, Nijaga, Rizal, Limarayon, Cacaransan, Malopalo, San Isidro, Bante, Amampacang, Bantian, Salvacion, Peña, Cagnipa, Binalew, Nabang, Quezon, Cabacongan, Sinidman Oriental, Longsob, Quirino, Bohang, Cagbilwang, and Roxas in the City of Calbayog","orig":"An Act Creating the Barrios of Kilikili, Acedillo, Dagum, Tomaleguis, Nijaga, Rizal, Limarayon, Cacaransan, Malopalo, San Isidro, Bante, Amampacang, Bantian, Salvacion, Peña, Cagnipa, Binalew, Nabang, Quezon, Cabacongan, Sinidman Oriental, Longsob, Quirino, Bohang, Cagbilwang, and Roxas in the City of Calbayog"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2466","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2466_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2196-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the City of Calbayog.\n(1) Barrio of Kilikili, consisting of the sitios of Guincatol-an, Cambahog, Somhag and Lomoy;\n(2) Barrio of Acedillo, consisting of the sitios of Bontay, Malorag, Palanas and Camatorog;\n(3) Barrio of Dagum, consisting of the sitios of Engagan, Nagboong, Labuyao and Guinkamalegan;\n(4) Barrio of Tomaleguis, consisting of the sitios of Rawis, Ba-ot, and Cagagting;\n(5) Barrio of Nijaga, consisting of the sitio of Nagboong Daco;\n(6) Barrio of Rizal, consisting of the sitios of Cawayan, Cag-abaca, Caballero and Cagboborac;\n(7) Barrio of Limarayon, consisting of the sitios of Gaway-gaway, Guintago-an, Cagsasaly and Lauong;\n(8) Barrio of Cacaransan, consisting of the sitios of Enora, Bontay, Camayze, Morabno, Elawod and Camalig;\n(9) Barrio of Malopalo, consisting of the sitios of Liguiron, Masarot, and Cagonga-an;\n(10) Barrio of San Isidro, consisting of the sitios of Nasipitan, Hitaosan and Cagbasiran;\n(11) Barrio of Bante, consisting of the sitios of Soboc, Egot, Borawosan and Tunga-a;\n(12) Barrio of Amampacang, consisting of the sitios of Burabod, Duro-ongan, Or. Baut and Oc. Lonoy;\n(13) Barrio of Bantian, consisting of the sitios of Mangenoo, Masapara, Cauloyanan and Palanas;\n(14) Barrio of Salvacion, consisting of the sitios of Cagmanipes-Daco, Borobadjing, Malobago and Onglob;\n(15) Barrio of Peña, consisting of the sitios of Cangoma-ud, Taboc, Canoctan Oc. and Cog-olango;\n(16) Barrio of Cagnipa, consisting of the sitios of Canoctan Or., Talahid, Bagacay and Culo;\n(17) Barrio of Binalew, consisting of the sitios of Baay, Sulop and Pingket;\n(18) Barrio of Nabang, consisting of the sitio of Tagcarisan;\n(19) Barrio of Quezon, consisting of the sitios of Loyang, Cabalawa, Datan, Dinanlan, Alalawig and Cambaisa;\n(20) Barrio of Cabacongan, consisting of the sitios of Lanquio, Esao and Henologan;\n(21) Barrio of Sinidman Or., consisting of the sitio of Caranas;\n(22) Barrio of Longsob, consisting of the sitios of Parasan, Cabadyangan and Longsob;\n(23) Barrio of Quirino, consisting of the sitios of Denaolan, Tabacno, Cagbayang and Talo-loan;\n(24) Barrio of Bohang, consisting of the sitios of Pagsanghang, Cag-aguingay and Caransan;\n(25) Barrio of Cagbilwang, consisting of the sitios of Cabugwan, Pungdol, Catan-agan, Capilihan and Cagbilwang left; and\n(26) Barrio of Roxas, consisting of the sitio of Lonoy and Minaudiong."}},{"id":"PH-H2196-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2197"] = {"id":"PH-H2197","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2467_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Pambujan市","en":"An Act Creating the Barrios of Tubang, Camangaran and San Isidro in the Municipality of Pambujan, Province of Samar","orig":"An Act Creating the Barrios of Tubang, Camangaran and San Isidro in the Municipality of Pambujan, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2467","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2467_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2197-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Pambujan, Province of Samar:\n(1) Barrio Tubang, consisting of the sitios of Irinlum and Bajuaticlum;\n(2) Barrio Camangaran, consisting of the sitios of Geyaot, Balud and Colawingan; and\n(3) Barrio San Isidro, consisting of the sitios of Anis-lagan, Nabaye, Guenalomsan and Gebonawan."}},{"id":"PH-H2197-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2198"] = {"id":"PH-H2198","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2468_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Palapag市","en":"An Act Creating the Barrios of Campidico, Magsaysay, Maragano, Nipa, Bagacay, Mabaras, Binay, Sumoroy, Sinalaran, Paysud and Osmeña, in the Municipality of Palapag, Province of Samar","orig":"An Act Creating the Barrios of Campidico, Magsaysay, Maragano, Nipa, Bagacay, Mabaras, Binay, Sumoroy, Sinalaran, Paysud and Osmeña, in the Municipality of Palapag, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2468","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2468_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2198-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Palapag, Province of Samar:\n(1) Barrio Campidico, consisting of the sitios of Tubay, Nasohong and Banica;\n(2) Barrio Magsaysay consisting of the sitios of Malihao, Napo and Cale;\n(3) Barrio Maragano, consisting of the sitios of Kalinawan, Canbisco, Mampogay, Cabotonan and Maitmait;\n(4) Barrio Nipa, consisting of the sitios of Doljongan, Libas, Cabarasan, Malobago, Dinodogho-an, Sumalidsid, Son-og and Panagdanan;\n(5) Barrio Bagacay, consisting of the sitios of Tubag, Pong-ol, Binatiklan, Manganino, Caghoguinog, Kanonghan, Pangodtan, Cagomasam, Capdanogan, Guindago-an, Hibatuan, Can-irib and Borac;\n(6) Barrio Mabaras, consisting of the sitios of Camayawan, Culipapa;\n(7) Barrio Binay, consisting of the sitios of Solangan, Lalangoyon, Doro-ongan, Bungalon and Inom-enom;\n(8) Barrio Sumoroy, consisting of the sitios of Guinparican, Tinampo, Guinpontingan, Cancalaton, Baho, Bolagsong and Salagan;\n(9) Barrio Sinalaran, consisting of the sitios of Labidao and Balud;\n(10) Barrio Paysud, consisting of the sitios of Cabongaan, Danao, Nabatasan and Darag; and\n(11) Barrio Osmeña, consisting of the sitios of Capirisan, Carogyao, Bongcag, Gadgad, Borac, Hibatuan and Alibangbang."}},{"id":"PH-H2198-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2199"] = {"id":"PH-H2199","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2469_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Las Navas市","en":"An Act Creating the Barrios of Quezon, Hinaonawan, Capoto-An, Victory, San Jorge, Sto. Tomas, Balugo, Quirino, Catoto-gan, Tagan-ayan, Hangi, Geguinta, Roxas, San Andres, San Jose, Del Pilar, Jolejole, Epao, San Isidro, Bugay, Lourdes, Lakandola, Matelarag and San Fernando in the Municipality of Las Navas, Province of Samar","orig":"An Act Creating the Barrios of Quezon, Hinaonawan, Capoto-An, Victory, San Jorge, Sto. Tomas, Balugo, Quirino, Catoto-gan, Tagan-ayan, Hangi, Geguinta, Roxas, San Andres, San Jose, Del Pilar, Jolejole, Epao, San Isidro, Bugay, Lourdes, Lakandola, Matelarag and San Fernando in the Municipality of Las Navas, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2469","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2469_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2199-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Las Navas, Province of Samar:\n(1) Barrio of Quezon, consisting of the sitios of Bayang, Egot, Caglebas, Panonorhon, Galotan, Malingon and Holempao;\n(2) Barrio of Hinaonawan, consisting of the sitios of Makatol, Linao, Pagdadalitan, Kauro-anan and Magtawid;\n(3) Barrio of Capoto-an, consisting of the sitios of Da-og, Cambeyawa, Baloto-an, Balagon, Malangrop, Eva and Pating;\n(4) Barrio of Victory, consisting of the sitios of Camanlay, Malapoy, Odiong, Dagopay, Taloto, Caglibas, Cagbatang, Pamalbagan, Banga and Macapito;\n(5) Barrio of San Jorge, consisting of the sitios of Dadanao, Mayanahao, Cambaong, Nasipit and Gaas;\n(6) Barrio of Sto. Tomas, consisting of the sitios of Hilabaan, Balocawe, Paghadnan and Cabaywa;\n(7) Barrio of Balugo, consisting of the sitios of Balugo, Rohag, and Polid;\n(8) Barrio of Quirino, consisting of the sitios of Paglilinti-an, Linao, Pangasi-an, Panlaran, Calingatangan, Cany-ayac, Catotobagan and Panding;\n(9) Barrio of Catoto-gan, consisting of the sitios of Lasa-on Cadadaha-an, Maybato and Carnaga;\n(10) Barrio of Tagan-ayan, consisting of the sitios of Cabayhan, Balerig, Hepeli, Macapenda, Guensoc-an and Panenehuran;\n(11) Barrio of Hangi, consisting of the sitios of Babtuhan, Palanas, Palijon and Lut-o;\n(12) Barrio of Geguinta, consisting of the sitios of Inoloran, Maylawa-an, Line-ad, Mangnirocan, Barayong and Mayoga;\n(13) Barrio of Roxas, consisting of the sitios of Bigaghon, Bugay, Nalumsan, Cambungad and Camaniwan;\n(14) Barrio of San Andres, consisting of the sitios of Malbog, Mabawang, Mugos, Cagtutu-og, Pun-od, Can-ayog and Guinbalut-an;\n(15) Barrio of San Jose, consisting of the sitios of Anongo, Tultula, Camangarin, Canlukisa and Mayapangan;\n(16) Barrio of Del Pilar, consisting of the sitios of Liro-an, Maglolo, Tagaw-acan, Balirig and Dap-dap;\n(17) Barrio of Jolejole, consisting of the sitios of Cabuntan, Cancuros, Malaibog and Butnga nga Dalan;\n(18) Barrio of Epao, consisting of the sitios of Nagcalahog, Pakakagaingan, Cabunga-an and Cansuming;\n(19) Barrio of San Isidro, consisting of the sitios of Himagango, Mabagna, Cagpapangao, Mocboc, Penipisacan and Cambagniohan;\n(20) Barrio of Bugay, consisting of the sitios of Cagbubulo, Lonoy, Cagdara-o, Limaro and Cagtitibac;\n(21) Barrio of Lourdes, consisting of the sitios of Tabon, Maydapdap, Caligbas, Caningag, Panoypoy, Maogay and Bacsal;\n(22) Barrio of Lakandola, consisting of the sitios of Cahagnaya-an, Arogayao, Polipog, Macaliwanag and Nabaye;\n(23) Barrio of Matelarag, consisting of the sitios of Caglebas and Babawang; and\n(24) Barrio San Fernando, consisting of the sitios of Palijon, Capongot and Lalyogan."}},{"id":"PH-H2199-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2200"] = {"id":"PH-H2200","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2470_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Lavezares市","en":"An Act Creating the Barrios of Valecuatro, Macarthur and To-og in the Municipality of Lavezares, Province of Samar","orig":"An Act Creating the Barrios of Valecuatro, Macarthur and To-og in the Municipality of Lavezares, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2470","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2470_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2200-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Lavezares, Province of Samar:\n(1) Barrio Valecuatro, consisting of the sitios of Anahaw, Tarangban, Napandong and Talisay-Libtong;\n(2) Barrio MacArthur, consisting of the sitios of Danao, Dorongan, Calpe, Bagacy, Senemanyan, Penoselan, Tanawan and Cagbabacong; and\n(3) Barrio To-og, consisting of the sitios of Mestranza, Guenbetinan, Maelje, Cenedman, Maghagonhong, Cocalazpean and Guin-Campojan."}},{"id":"PH-H2200-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2201"] = {"id":"PH-H2201","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2471_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Laoang市","en":"An Act Creating the Barrios of Bonglew, Cabagoan, Tarosan, Inamlan, Bobolusan, Cancahepus, Rombang, Vigo, Yapas, San Antonio, Gregorio B. Tan, Aroganga, Cabagngan, Burado, Agrupacion, Antipolo, Lawa-An, Canyomanao, Lanobe, Tenoblan and Suba in the Municipality of Laoang, Province of Samar","orig":"An Act Creating the Barrios of Bonglew, Cabagoan, Tarosan, Inamlan, Bobolusan, Cancahepus, Rombang, Vigo, Yapas, San Antonio, Gregorio B. Tan, Aroganga, Cabagngan, Burado, Agrupacion, Antipolo, Lawa-An, Canyomanao, Lanobe, Tenoblan and Suba in the Municipality of Laoang, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2471","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2471_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2201-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Laoang, Province of Samar:\n(1) Barrio of Bonglew, consisting of the sitios of Marubaybay, Beseig, Cagsiburan and Calo-ocan;\n(2) Barrio of Cabagoan, consisting of the sitios of Bonot, Matames, Cabagoan and Cangcaligong;\n(3) Barrio of Tarosan, consisting of the sitios of Kikirohan and Campondong;\n(4) Barrio of Inamlan, consisting of the sitios of Capasgapas;\n(5) Barrio of Bobolusan, consisting of the sitios of Guencalerohan, Dongon, Dampega, Bon-ot, Herosalem and Guenlambekihan;\n(6) Barrio of Cancahepus, consisting of the sitios of Caco-olan, Taboc and Babantayan;\n(7) Barrio of Rombang, consisting of the sitios of Lanobe, Cagotsan, Cancarajog and Carawang;\n(8) Barrio of Vigo, consisting of the sitios of Malobago, Nalibon, Macalanos, Camalig, Benalenan and Nahibang;\n(9) Barrio of Yapas, consisting of the sitios of Tinoblan, Libas and Tomindao;\n(10) Barrio of San Antonio, consisting of the sitios of Malobago, Lobogon, Larac, De-it, Hangtud, Bartulo and Son-og;\n(11) Barrio of Gregorio B. Tan, consisting of the sitios of Galatan and Camparicay;\n(12) Barrio of Aroganga, consisting of the sitios of Sase-on, Manaybanay and Balwarte;\n(13) Barrio of Cabagngan, consisting of the sitios of San Vicente and Pinangorayan;\n(14) Barrio of Burabod, consisting of the sitios of Vega, Cagnaga, Bagsang and Amambolanon;\n(15) Barrio of Agrupacion, consisting of the sitios of Cawilan, Lengawin and Nabioso;\n(16) Barrio of Antipolo, consisting of the sitios of Da-o, Camilig and Balocawe;\n(17) Barrio of Lawa-an, consisting of the sitio of Tipbao;\n(18) Barrio of Canyomanao, consisting of the sitio of Canamocan;\n(19) Barrio of Lanobe, consisting of the sitio of Tawiron;\n(20) Barrio of Tenoblan, consisting of the sitio of Carawag; and\n(21) Barrio of Suba."}},{"id":"PH-H2201-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2202"] = {"id":"PH-H2202","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2472_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Catubig市","en":"An Act Creating the Barrios of Tongodnon, Irawahan, Giparayan, Calingnan, Canuctan and Guibwangan in the Municipality of Catubig, Province of Samar","orig":"An Act Creating the Barrios of Tongodnon, Irawahan, Giparayan, Calingnan, Canuctan and Guibwangan in the Municipality of Catubig, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2472","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2472_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2202-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Catubig, Province of Samar:\n(1) Barrio of Tongodnon, consisting of the sitio of Maykabaan;\n(2) Barrio of Irawahan, consisting of the sitios of Matadag, Imalhos and Cognonoc;\n(3) Barrio of Giparayan, consisting of the sitio of Hialob;\n(4) Barrio of Calingnan, consisting of the sitios of Sowa and Guinsorjan;\n(5) Barrio of Canuctan, consisting of the sitios of Caloocan, Gibaca-an and Amambucad; and\n(6) Barrio of Guibwangan, consisting of the sitio of Canbebre."}},{"id":"PH-H2202-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2203"] = {"id":"PH-H2203","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2473_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Catarman市","en":"An Act Creating the Barrios of Guba, Hibolwangan, Cal-Egang, Liberty, Bayho, Paticua, Gulatan, Genatad, Daganas, Macagtas, Gebulwangan, Cag-Abaca, Upper Caynaga, Getigo and Capipi-An in the Municipality of Catarman, Province of Samar","orig":"An Act Creating the Barrios of Guba, Hibolwangan, Cal-Egang, Liberty, Bayho, Paticua, Gulatan, Genatad, Daganas, Macagtas, Gebulwangan, Cag-Abaca, Upper Caynaga, Getigo and Capipi-An in the Municipality of Catarman, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2473","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2473_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2203-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Catarman, Province of Samar:\n(1) Barrio of Guba, consisting of the sitios of Cagoange, Guba, Colarema, Loyagay, Catangbo-an and Bocsol;\n(2) Barrio of Hibolwangan, consisting of the sitios of Talahid, Deit, Talorag-on, Maghepid, Somalog, Boy-an, Cag-agengay and Cammaria;\n(3) Barrio of Cal-egang, consisting of the sitios of Cal-egang, Mag-agong-ong, Guinperahan, Gebabao-gan, Pelit and Banijet;\n(4) Barrio of Liberty, consisting of the sitios of Hapnit, Poyao, Bango, Caangyapan and Uppeo;\n(5) Barrio of Bayho, consisting of the sitios of Hertigan, Taloto-an, Cabato-an and Lower Caynaga;\n(6) Barrio of Paticua, consisting of the sitios of Hemanalod, Awang, Nagcahog, Olaogan, and Sumalog;\n(7) Barrio of Gulatan, consisting of the sitios of Baga, Kaglangboy, Babaras and Palanas;\n(8) Barrio of Genatad, consisting of the sitios of Caglibas, San-og, Catoto-ogan and Camogdan;\n(9) Barrio of Daganas, consisting of the sitios of Segad, Suga, Iraya Suga, Benog, Wate, Oway, Tamburosan, Mametin and Lib-jo;\n(10) Barrio of Macagtas, consisting of the sitios of Pelit, Balud, Caraja-an and Macopa;\n(11) Barrio of Gebulwangan, consisting of the sitios of Kinaatban, Caboyu-an, Maghipid, Di-it, Nabawang, Boy-an Cag-angingay and Somalog;\n(12) Barrio of Cag-abaca, consisting of the sitios of Cagbabahe, Iba, Caganahao, Oson, Son-og, Cabatangan, Guimpohagan, Candanda, Cabadiangan and Ca-angyapan;\n(13) Barrio of Upper Caynaga, consisting of the sitios of Tura and Cabalocawi-an;\n(14) Barrio of Getigo, consisting of the sitios of Mahagna, Panaghiran, Ca-olayanan, Salimpawod, Patong and Hinaboyan; and\n(15) Barrio of Capipi-an, consisting of the sitios of Cagomondong, Mangpang, Cababalayan, Cabalocawi-an and Pangi."}},{"id":"PH-H2203-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2204"] = {"id":"PH-H2204","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2474_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Allen市","en":"An Act Creating the Barrio of Caputi-An, Bonifacio, Maxvilla, Buenos Aires, Buenasuerte and San Lazaro in the Municipality of Allen, Province of Samar","orig":"An Act Creating the Barrio of Caputi-An, Bonifacio, Maxvilla, Buenos Aires, Buenasuerte and San Lazaro in the Municipality of Allen, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2474","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2474_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2204-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Allen, Province of Samar:\n(1) Barrio of Caputi-an, consisting of the sitios of Longib, Danao and Bangon;\n(2) Barrio of Bonifacio, consisting of the sitios of Egot, Salay, Mamatayan and Palacpac;\n(3) Barrio of Maxvilla, consisting of the sitios of Pinayagan, Palanas, Cantipok, and Guinbog-noan;\n(4) Barrio of Buenos Aires (formerly Borobodiongan), consisting of the sitios of Patag, Canlong-canlong, Lo-ok and Vesoria;\n(5) Barrio of Buensuerte, consisting of the sitios of To-og, Cag-olango, Pinamonayan and Cadadiangaoan; and\n(6) Barrio of San Lazaro, consisting of the sitios of Sorok, Honop, and Bunglasan."}},{"id":"PH-H2204-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2205"] = {"id":"PH-H2205","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2475_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Rizal市","en":"An Act Creating the Barrio of General Luna in the Municipality of Rizal, Province of Nueva Ecija","orig":"An Act Creating the Barrio of General Luna in the Municipality of Rizal, Province of Nueva Ecija"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2475","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2475_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2205-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of General Luna, Francis, Tila Banca, Nambabacalan and Pilatoc of the barrio of Canaan, Municipality of Rizal, Province of Nueva Ecija, are separated from said barrio of Canaan and constituted into a barrio to be known as the barrio of General Luna."}},{"id":"PH-H2205-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2206"] = {"id":"PH-H2206","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2476_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Rizal市","en":"An Act Converting the Sitio of Manlungay of the Barrio of Canaan, Municipality of Rizal, Province of Nueva Ecija, into a Barrio of the Said Municipality to be Known as Barrio Villa Paraiso","orig":"An Act Converting the Sitio of Manlungay of the Barrio of Canaan, Municipality of Rizal, Province of Nueva Ecija, into a Barrio of the Said Municipality to be Known as Barrio Villa Paraiso"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2476","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2476_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2206-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Manlungay of the barrio of Canaan, Municipality of Rizal, Province of Nueva Ecija, is separated from said barrio of Canaan and constituted into a barrio of the said municipality to be known as Barrio Villa Paraiso."}},{"id":"PH-H2206-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2207"] = {"id":"PH-H2207","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2477_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Calolbon市","en":"An Act Creating the Barrio of San Isidro in the Municipality of Calolbon, Province of Catanduanes","orig":"An Act Creating the Barrio of San Isidro in the Municipality of Calolbon, Province of Catanduanes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2477","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2477_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2207-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of San Isidro in the Municipality of Calolbon, Province of Catanduanes, is converted into a barrio of said municipality to be known as the barrio of San Isidro."}},{"id":"PH-H2207-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
