  FT["PH-H2210"] = {"id":"PH-H2210","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2480_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bagamanoc市","en":"An Act Creating Certain Barrios in the Municipality of Bagamanoc, Province of Catanduanes","orig":"An Act Creating Certain Barrios in the Municipality of Bagamanoc, Province of Catanduanes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2480","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2480_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2210-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Panuto, Pangcayanan, Quegaray and Cajan in the Municipality of Bagamanoc, Province of Catanduanes, are converted into barrios of said municipality to be known as the barrios of Panuto, Pangcayanan, Quegaray and Cajan, respectively."}},{"id":"PH-H2210-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
