  FT["PH-H2212"] = {"id":"PH-H2212","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2482_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Tagkawayan市","en":"An Act Creating Certain Barrios in the Municipality of Tagkawayan, Province of Quezon","orig":"An Act Creating Certain Barrios in the Municipality of Tagkawayan, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2482","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2482_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2212-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of San Jose and San Pedro in the barrio of Bagong Silang, Municipality of Tagkawayan, Province of Quezon, are separated from said barrios and constituted into distinct and independent barrios of said municipality to be known as the barrios of San Jose and San Pedro, respectively.\nThe barrio of San Jose shall be bounded in the North by Barrio of San Pedro, on the East by Barrio Bagong Silang, on the South by Cabibihan, and on the West by Gumihan Creek; and the barrio of San Pedro shall be bounded on the North by public forest, one the East by public forest, on the South by Barrio Sta. Monica, and on the West by municipal boundary of the municipalities of Calauag and Tagkawayan."}},{"id":"PH-H2212-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
