  FT["PH-H2222"] = {"id":"PH-H2222","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2492_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Santa Rosa Elementary School in the Municipality of Baco, Province of Oriental Mindoro, to Julio Hernandez Memorial School","orig":"An Act Changing the Name of Santa Rosa Elementary School in the Municipality of Baco, Province of Oriental Mindoro, to Julio Hernandez Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2492","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2492_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2222-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Santa Rosa Elementary School in the Municipality of Baco, Province of Oriental Mindoro, is hereby changed to Julio Hernandez Memorial School."}},{"id":"PH-H2222-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2223"] = {"id":"PH-H2223","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2493_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Lipa市","en":"An Act Creating the Barrio of San Guillermo in the City of Lipa","orig":"An Act Creating the Barrio of San Guillermo in the City of Lipa"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2493","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2493_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2223-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Sala and Pagolingling Bata in the City of Lipa are constituted into a distinct and independent barrio of said City to be known as the barrio of San Guillermo."}},{"id":"PH-H2223-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2224"] = {"id":"PH-H2224","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2494_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Lipa市","en":"An Act Creating the Barrio of Bulaklakan in the City of Lipa","orig":"An Act Creating the Barrio of Bulaklakan in the City of Lipa"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2494","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2494_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2224-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Palaclacan, Latag and Bulalakao in the City of Lipa are separated from the barrio of Pinagtongulan, and are constituted into a distinct and independent barrio of said city to be known as the barrio of Bulaklakan."}},{"id":"PH-H2224-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2225"] = {"id":"PH-H2225","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2495_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Lipa市","en":"An Act Creating the Barrio of Malitlit in the City of Lipa","orig":"An Act Creating the Barrio of Malitlit in the City of Lipa"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2495","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2495_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2225-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Malitlit in the City of Lipa is converted into a barrio of said city to be known as the barrio of Malitlit."}},{"id":"PH-H2225-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2226"] = {"id":"PH-H2226","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2496_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Mabinay in the Province of Negros Oriental","orig":"An Act Creating the Municipality of Mabinay in the Province of Negros Oriental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2496","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2496_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2226-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Baliw, Landas, Langao, Abis, Himocdongon, Bato, Luyang Namangka, Tadlong, Lumbangan, Panyabonan, Tubod, Inapoy, Barras and Banban of Barrio Bagtic, Municipality of Bais, Province of Negros Oriental, are separated from said municipality and are constituted into a distinct and independent municipality to be known as the Municipality of Mabinay, Province of Negros Oriental."}},{"id":"PH-H2226-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The seat of government shall be in the Mabinay proposed townsite in sitio Tadlong, or in any of the sitios therein which the municipal council by two-thirds vote may hereafter propose: Provided, That if the municipal council fails or omits to propose a different site within one year after the organization of the municipal government, the permanent site shall be the Mabinay proposed townsite: Provided, further, That should the council propose a different site within the period stated, that site so proposed shall be the seat of the municipal government."}},{"id":"PH-H2226-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President of the Philippines with the consent of the Commission on Appointments not earlier than the first of January, nineteen hundred and sixty, and shall hold office until their successors shall have been elected in the next general elections for provincial and municipal officials, and shall have been duly qualified."}},{"id":"PH-H2226-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect on January first, nineteen hundred and sixty.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2227"] = {"id":"PH-H2227","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2497_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Abulug市","en":"An Act Creating the Barrio of Lucban in the Municipality of Abulug, Province of Cagayan","orig":"An Act Creating the Barrio of Lucban in the Municipality of Abulug, Province of Cagayan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2497","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2497_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2227-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Lucban in the Municipality of Abulug, Province of Cagayan, is converted into a barrio of said municipality to be known as the barrio of Lucban."}},{"id":"PH-H2227-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2228"] = {"id":"PH-H2228","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2498_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Guihulungan市","en":"An Act Creating the Barrios of Luz, Linantuyan and Hilaitan in the Municipality of Guihulungan, Province of Negros Oriental","orig":"An Act Creating the Barrios of Luz, Linantuyan and Hilaitan in the Municipality of Guihulungan, Province of Negros Oriental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2498","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2498_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2228-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following barrios are hereby created in the Municipality of Guihulungan, Province of Negros Oriental:\n1. Barrio Luz, consisting of the sitios of Magbala-as, (large), Cambalo, Dadiangao, Agbabakid, Banogbanog, Hinoba-an (small), Taluktok, Hinogpayan, Balingos, Kanapu-an, Mahilig, Takung and Bonbong;\n2. Barrio Linantuyan, consisting of the sitios of Magbala-as (small), Aya (small), Magkilignit, Taloto, Hinoba-an (large), Gusa (small), Alamag and Salong; and\n3. Barrio Hilaitan, consisting of the sitios of Marilao, Ilaya, Kambulongnon, Busay, Danao, Manhantik, Tinagducan, Katawan, Mambug, Panlubiran and Himaya."}},{"id":"PH-H2228-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2229"] = {"id":"PH-H2229","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2499_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Palompon市","en":"An Act Creating Certain Barrios in the Municipality of Palompon, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Palompon, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2499","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2499_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2229-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Palompon, Province of Leyte, are converted into barrios thereof, as follows:\n1. The sitio of Caduhaan to be known as the barrio of Caduhaan;\n2. The sitio of Cambakbak to be known as the barrio of Cambakbak;\n3. The sitio of San Guillermo to be known as the barrio of San Guillermo;\n4. The sitio of Lu-uk to be known as the barrio of San Isidro.\n5. The sitio of Lat-osan to be known as the barrio of Lat-osan;\n6. The sitio of San Joaquin to be known as the barrio of San Joaquin; and\n7. The sitio of Cangmuya to be known as the barrio of Cangmuya."}},{"id":"PH-H2229-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2230"] = {"id":"PH-H2230","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2500_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Convert Certain Sitios of the Municipality of Looc, Province of Romblon, into Barrios","orig":"An Act to Convert Certain Sitios of the Municipality of Looc, Province of Romblon, into Barrios"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2500","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2500_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2230-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Clagonsao and Bonlao of Barrio Tugdan, the sitios of San Isidro (Icogan) and Comod-om of Barrio Alcantara, the sitios of Guinhaya-an, Manhac and Tuguis of Barrio Punta, and the sitios of Camandag and Balatucan of Barrio Buenavista, all in the Municipality of Looc, province of Romblon, are converted into barrios of the same names."}},{"id":"PH-H2230-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2231"] = {"id":"PH-H2231","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2501_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of the Caparan Primary School and Dalangin Primary School in the Municipality of Ipil, Province of Zamboanga del Sur, to Tiayon Primary School and DARol Moslem Primary School, Respectively","orig":"An Act Changing the Names of the Caparan Primary School and Dalangin Primary School in the Municipality of Ipil, Province of Zamboanga del Sur, to Tiayon Primary School and DARol Moslem Primary School, Respectively"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2501","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2501_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2231-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of Caparan Primary School and Dalangin Primary School, both in the Municipality of Ipil, Province of Zamboanga del Sur, are changed to Tiayon Primary School and Darol Moslem Primary School, respectively."}},{"id":"PH-H2231-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2232"] = {"id":"PH-H2232","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2502_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Zamboanga del Sur","orig":"An Act Creating Certain Barrios in the Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2502","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2502_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2232-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Bolarong, Talanusa, Guinimanan, Bius, Linoguayan, Kapatagan, Waling Waling, Limason, Lonib, Cogon, Lumbog, Macaulay, Limbatong, Tulapok, Calian and Igat Islan in the Municipality of Margosatubig, province of Zamboanga del Sur, are converted into barrios of said municipality to be known as the barrios of Bolarong, Talanusa, Guinimanan, Bius, Linoguayan, Kapatagan, Waling Waling, Limason, Lonib, Cogon, Lumbog, Macaulay, Limbatong, Tulapok, Calian, and Igat Island, respectively."}},{"id":"PH-H2232-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Loy-a in the Municipality of San Pablo, same province, is converted into a barrio of said municipality to be known as the barrio of Regla."}},{"id":"PH-H2232-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2233"] = {"id":"PH-H2233","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2503_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Aborlan市","en":"An Act Creating Certain Barrios in the Municipality of Aborlan, Province of Palawan","orig":"An Act Creating Certain Barrios in the Municipality of Aborlan, Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2503","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2503_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2233-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Tinagong-dagat, Apoaporawan and Malatgao in the Municipality of Aborlan, Province of Palawan, are converted into barrios of said municipality to be known as the barrios of Tinagong-dagat, Sandoval and Malatgao, respectively."}},{"id":"PH-H2233-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2234"] = {"id":"PH-H2234","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2504_1959.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Surigao","orig":"An Act Creating Certain Barrios in the Province of Surigao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2504","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2504_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2234-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Bognan, Mone, Luha, Tumanan, Sta. Cruz, Sute, Tabon and Caguyao in the Municipality of Bislig, province of Surigao, are converted into barrios of said municipality to be known as the barrios of Bognan, Mone, Luha, Tumanan, Sta. Cruz, Sute, Tabon and Caguyao, respectively."}},{"id":"PH-H2234-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Lahi, Hayangabon, Cagdianao, Cabugo and Sapa in the Municipality of Claver, same province, are converted into barrios of said municipality to be known as the barrios of Lahi, Hayangabon, Cagdianao, Cabugo and Sapa, respectively."}},{"id":"PH-H2234-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Balibadon in the Municipality of Cortes, same province, is converted into a barrio of said municipality to be known as the barrio of Balibadon."}},{"id":"PH-H2234-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitios of Caman-onan, Lahi, Cambo-ayon and Anibongan in the Municipality of Gigaquit, same province, are converted into barrios of said municipality to be known as the barrios of Caman-onan, Lahi, Cambo-ayon and Anibongan, respectively."}},{"id":"PH-H2234-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitios of Cambatong and Tagasaka in the Municipality of Hinatuan, same province, are converted into barrios of said municipality to be known as the barrios of Cambatong and Tagasaka, respectively."}},{"id":"PH-H2234-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitios of Cabacungan, Unidad, Kinayan, Barobo, Anibungan, Diatagon, Javier, San Vicente, Amaga, Cangbagang and Bahi in the Municipality of Liangan, same province, are converted into barrios of said municipality to be known as the barrios of Cabacungan, Unidad, Kinayan, Barobo, Anibungan, Diatagon, Javier, San Vicente, Amaga, Cangbagang and Bahi, respectively."}},{"id":"PH-H2234-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sitio of Cabiton-an in the Municipality of Loreto, same province, is converted into a barrio of said municipality to be known as the barrio of Magsaysay."}},{"id":"PH-H2234-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sitios of San Jose, Dayano and Ombong in the Municipality of Mainit, same province, are converted into barrios of said municipality to be known as the barrios of San Jose, Dayano and Ombong, respectively."}},{"id":"PH-H2234-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The sitios of Cagtenae, Cawayan, Hanagdong and Carihatag in the Municipality of Malimono, same province, are converted into barrios of said municipality to be known as the barrios of Cagtenae, Cayawan, Hanagdong and Carihatag, respectively."}},{"id":"PH-H2234-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The sitio of Bito-on in the Municipality of Numacia, same province, is converted into a barrio of said municipality to be known as the barrio of Bito-on."}},{"id":"PH-H2234-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The sitios of Garcia, Magsaysay and Coboy in the Municipality of Sapao, same province, are converted into barrios of said municipality to be known as the barrios of Garcia, Magsaysay and San Juan, respectively."}},{"id":"PH-H2234-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The sitios of Poctoy and Mayag in the Municipality of Surigao, same province, are converted into barrios of said municipality to be known as the barrios of Poctoy and Mayag, respectively."}},{"id":"PH-H2234-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The sitios of Libas Gua, Barras, Layog, Jubang, Umbay, Carromata, Kinabigtasan, Bangsud, Ciagao, Maitum, Cayale, Bajao and Dayo-an in the Municipality of Tago, same province, are converted into barrios of said municipality to be known as the barrios of Libas Gua, Barras, Layog, Jubang, Umbay, Carromata, Kinabigtasan, Bangsud, Ciagao, Maitum, Cayale, Bajao and Dayo-an, respectively."}},{"id":"PH-H2234-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2235"] = {"id":"PH-H2235","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2505_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of DARaga, Province of Albay, to Municipality of Locsin","orig":"An Act Changing the Name of the Municipality of DARaga, Province of Albay, to Municipality of Locsin"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2505","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2505_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2235-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Daraga, Province of Albay, is changed to Municipality of Locsin."}},{"id":"PH-H2235-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2236"] = {"id":"PH-H2236","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2506_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Puerto Princesa市","en":"An Act Creating the Barrios of Santa Cruz in the Municipality of Puerto Princesa, Province of Palawan","orig":"An Act Creating the Barrios of Santa Cruz in the Municipality of Puerto Princesa, Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2506","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2506_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2236-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Kalatubog and Kilometer 32 of Puerto Princesa North Road in the Municipality of Puerto Princesa, Province of Palawan, are constituted into a barrio of said municipality to be known as the barrio of Santa Cruz."}},{"id":"PH-H2236-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2237"] = {"id":"PH-H2237","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2507_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Lupon市","en":"An Act Creating Certain Barrios in the Municipality of Lupon, Province of Davao","orig":"An Act Creating Certain Barrios in the Municipality of Lupon, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2507","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2507_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2237-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Lupon, Province of Davao, are converted into barrios of said municipality to be known as follows:\nSitio Cuabo to Barrio Cuabo; Sitio San Roque to Barrio San Roque; Sitio Crossing Manikling to Barrio Crossing Manikling; Sitio Dogmanon to Barrio Dogmanon; Sitio Eva to Barrio Eva; Sitio Kabangkalan to Barrio Kabangkalan; Sitio Magsaysay to Barrio Magsaysay; Sitio San Jose to Barrio San Jose; Sitio Kauswagon to Barrio Kauswagon; Sitio Kalubihan to Barrio Kalubihan; Sitio Mugbongcugon to Barrio Mugbongcugon; Sitio Kabaddiangan to Barrio Kabaddiangan; Sitio Kalapagan to Barrio Kalapagan; Sitio San Vicente to Barrio San Vicente; Sitio Maragatas to Barrio Maragatas; and Sitio Mahayag to Barrio Mahayag."}},{"id":"PH-H2237-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2238"] = {"id":"PH-H2238","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2508_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Santo Domingo High School in the Municipality of Santo Domingo, Province of Nueva Ecija, to Julia Ortiz Luis High School","orig":"An Act Changing the Name of the Santo Domingo High School in the Municipality of Santo Domingo, Province of Nueva Ecija, to Julia Ortiz Luis High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2508","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2508_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2238-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Santo Domingo High School in the Municipality of Santo Domingo, Province of Nueva Ecija, is changed to Julia Ortiz Luis High School."}},{"id":"PH-H2238-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2239"] = {"id":"PH-H2239","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2509_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Ampatuan市","en":"An Act Creating the Municipality of Ampatuan, Province of Cotabato","orig":"An Act Creating the Municipality of Ampatuan, Province of Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2509","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2509_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2239-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Decalungan, Esperanza, Kauran, Manibba (Banaba), Matiompong, Kalandagan, Kayakaya, Upper Mao, Lower Mao, Guinibon, Makaubas, Buluan, Kamasi, Sampao, Upper Kakal, Lower Kakal, Tuka, Maganoy, Kaliawa, Malatimon, Kapimpilan, Laguinding and Timbangan, Municipality of Datu Piang, Province of Cotabato, are separated from said municipality, and are constituted into a district and independent municipality to be known as the Municipality of Ampatuan, Province of Cotabato, with the seat of government at the present site of the barrio of Decalungan, and the boundary of this new municipality shall be more definitely defined as follows:\n\"Beginning at Cabuban Bridge, on the Cotabato-Dalican-Allah Road, going due west to a point on the boundary line of the municipalities of Dinaig and Upi; thence going on a southwesterly direction following the boundary line of Dinaig and Upi to a point following the boundary lines of the municipalities of Lebak, Upi, Datu Piang and Dinaig meet; thence going on a southeasterly direction following the boundary line of the municipalities of Lebak and Datu Piang to a point where the boundary lines of the municipalities of Lebak, Datu Piang and Isulan meet; thence going due east following the boundary line of the municipalities of Datu Piang and Isulan to Allah Bridge, on the Cotabato-Dalican-Allah Road; thence going on a northeasterly direction following the course of the Allah River downstream to the junction of the Allah and Kapingkong Rivers, thence going on a northwesterly direction following the Allah River downstream to the junction of the Allah and Cabulnan Rivers; thence going on a southwesterly direction following the course of the Cotabato-Dalican-Allah Road, the point of beginning.\"\\"}},{"id":"PH-H2239-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be appointed by the President, with the consent of the Commission on Appointments, and shall hold office until their successors shall have been elected in the next general elections for local officials and shall have qualified."}},{"id":"PH-H2239-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2240"] = {"id":"PH-H2240","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2510_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Salug市","en":"An Act Creating the Municipality of Salug, Province of Zamboanga del Norte","orig":"An Act Creating the Municipality of Salug, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2510","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2510_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2240-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Salug, Mucas, Libertad, Tambalang, Balacan, Danao, Caracol, Canawan, Bacong, Lipakan, and Palandok in the Municipality of Liloy, Province of Zamboanga del Norte, are separated from said municipality, and are constituted into a distinct and independent municipality to be known as the Municipality of Salug, same province, with the seat of government located at the site of the present barrio of Mucas."}},{"id":"PH-H2240-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be appointed by the President, with the consent of the Commission on Appointments, and shall hold office until their successors shall have been elected in the next general elections for local officials and shall have qualified."}},{"id":"PH-H2240-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2241"] = {"id":"PH-H2241","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2511_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Fixing the Boundary Line Between the Municipalities of Allen and San Isidro Province of Samar","orig":"An Act Fixing the Boundary Line Between the Municipalities of Allen and San Isidro Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2511","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2511_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2241-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The boundary line between the municipalities of Allen and San Isidro, Province of Samar, shall be the center of the Mawo River up to the intersection of Mawo River and Igot River (San Ramon Creek), and from the center of the mount of Igot River to the intersection of Igot River and Binalabag Creek which runs eastward up to the boundary of the Municipality of San Jose."}},{"id":"PH-H2241-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of San Isidro shall include the barrios of San Ramon, Erenas, San Juan, Palanit, Veriato, Acedillo, Tangolan, Buenavista, Among, Happy Valley, Caaguit-itan, Corocolab-og and Caglanipao."}},{"id":"PH-H2241-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2242"] = {"id":"PH-H2242","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2512_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Transferring the Seat of Government of Taluksangay District, City of Zamboanga, to Pasilmanta, Sakol Island","orig":"An Act Transferring the Seat of Government of Taluksangay District, City of Zamboanga, to Pasilmanta, Sakol Island"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2512","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2512_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2242-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The seat of government of Taluksangay District, City of Zamboanga, is hereby transferred from Taluksangay proper to Pasilmanta, Sakol Island."}},{"id":"PH-H2242-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2243"] = {"id":"PH-H2243","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2513_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Defining the Boundary Between the Municipalities of Polillo and Burdeos, Province of Quezon","orig":"An Act Defining the Boundary Between the Municipalities of Polillo and Burdeos, Province of Quezon"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2513","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2513_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2243-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of Kaniwan situated between the municipalities of Polillo and Burdeos, making Pilion River as the boundary between the aforesaid municipalities."}},{"id":"PH-H2243-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2244"] = {"id":"PH-H2244","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2514_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Bansud in the Province of Oriental Mindoro","orig":"An Act Creating the Municipality of Bansud in the Province of Oriental Mindoro"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2514","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2514_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2244-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Tiguisan I, Alcadesma, Salcedo, Rosacara, Villa-Pag-asa, Putput, New Bansud, Old Bansud, Corazon Lancauan and Sumagui are separated from the Municipality of Bongabon, Province of Oriental Mindoro, and are constituted into a distinct and independent municipality to be known as the Municipality of Bansud, same province, with the seat of government to be located at the site of the present barrio of New Bansud."}},{"id":"PH-H2244-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President, with the consent of the Commission on Appointments, and shall hold office until their successors shall have been elected in the next general elections for local officials and shall have qualified."}},{"id":"PH-H2244-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2245"] = {"id":"PH-H2245","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2515_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Amend Section One of Republic Act Numbered Nineteen Hundred Seventy-Two","orig":"An Act to Amend Section One of Republic Act Numbered Nineteen Hundred Seventy-Two"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2515","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2515_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2245-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Nineteen hundred seventy-two is amended to read as follow:\nSec. 1 . The barrios of Ibung and Bintawan, Municipality of Solano, Province of Nueva Vizcaya, are separated from said municipality and are constituted into a distinct and independent municipality to be known as the Municipality of Villa Verde, Province of Nueva Vizcaya, with the seat of government at the site of the present barrio of Bintawan: Provided, However, That within a year from approval hereof, by a vote of two-third of all the members of the municipal council elected in the general elections of nineteen hundred and fifty-nine for local officials, such seat of government may be transferred to any other site.\""}},{"id":"PH-H2245-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2246"] = {"id":"PH-H2246","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2516_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act to Establish a National Agricultural High School in the Municipality of Salcedo, Province of Samar, to be Known as the Southern Samar National Agricultural School, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish a National Agricultural High School in the Municipality of Salcedo, Province of Samar, to be Known as the Southern Samar National Agricultural School, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2516","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2516_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2246-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Public Schools, a national agricultural school in the Municipality of Salcedo, Province of Samar, at a suitable site to be selected by said Director, to be known as the Southern Samar National Agricultural School."}},{"id":"PH-H2246-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the recommendation of the Director of Public Schools, the President shall set aside and reserve such portion of the public lands located in the Municipality of Salcedo of said province, as may be necessary and convenient for the establishment of the said school and of its farm site."}},{"id":"PH-H2246-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said school during the fiscal year ending June thirty, nineteen hundred sixty. Such sums as may be necessary for its operation and maintenance in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2246-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon the date the funds authorized herein to be appropriated shall have been provided for.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2247"] = {"id":"PH-H2247","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2517_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bunawan市","en":"An Act Creating the Municipality of Bunawan, Province of Agusan","orig":"An Act Creating the Municipality of Bunawan, Province of Agusan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2517","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2517_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2247-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The municipal districts of Mambili, Bunawan, Libertad, Basa, Tudela, San Isidro, Santa Maria, Trento, Cuevas and San Salvacion, together with the Villages of San Marcos and San Ignacio in the Province of Agusan are constituted into a distinct and independent municipality to be known as the Municipality of Bunawan, with the seat of government at the present site of the Municipal District of Bunawan. The said municipality shall be bounded in the North by Mandawiton and Mambogongon lakes and the Municipality of San Francisco, on the East by the Municipality of San Francisco and the Province of Surigao, of the South by the Province of Davao, and on the West by the municipal districts of Veruela, Sta. Josefa, Patrocinio and the village of San Gabriel."}},{"id":"PH-H2247-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President, with the consent of the Commission on Appointments, and shall hold office until their successors shall have been elected in the next general elections for local officials and shall have qualified."}},{"id":"PH-H2247-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2248"] = {"id":"PH-H2248","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2518_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立San Francisco市","en":"An Act Creating the Municipality of San Francisco, Province of Agusan","orig":"An Act Creating the Municipality of San Francisco, Province of Agusan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2518","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2518_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2248-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The municipal districts of Borbon, Ebro, Novele, Cabawan, Rosario, Alegria, Cabanto and San Francisco in the Province of Agusan are constituted into a distinct and independent municipality to be known as the Municipality of San Francisco, same province. The seat of government shall be located at the site of the present Municipal District of San Francisco."}},{"id":"PH-H2248-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President, with the consent of the Commission on Appointments, and shall hold office until their successors shall have been elected in the next general elections for local officials and shall have qualified."}},{"id":"PH-H2248-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2249"] = {"id":"PH-H2249","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2519_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Municipality of Saguday in the Province of Nueva Vizcaya","orig":"An Act Creating the Municipality of Saguday in the Province of Nueva Vizcaya"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2519","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2519_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2249-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Saguday, La Paz, Salvacion and Sto. Tomas are separated from the Municipality of Diffun, and the barrios of Dibol, Tres Reyes and Mangandingay are separated from the Municipality of Aglipay, all in the Province of Nueva Vizcaya, and constituted into a new and separate municipality of said province to be known as the Municipality of Saguday, with the seat of government at the present site of the barrio of Saguday."}},{"id":"PH-H2249-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor and councilors of the new municipality shall be appointed by the President of the Philippines with the consent of the Commission on Appointments, and shall hold office until their successors shall have been elected and shall have qualified."}},{"id":"PH-H2249-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2250"] = {"id":"PH-H2250","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2520_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Libog, Province of Albay, to Municipality of Sto. Domingo","orig":"An Act Changing the Name of the Municipality of Libog, Province of Albay, to Municipality of Sto. Domingo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2520","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2520_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2250-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipality of Libog, Province of Albay, shall hereafter be known as the Municipality of Sto. Domingo."}},{"id":"PH-H2250-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2251"] = {"id":"PH-H2251","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2522_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Santol I Elementary School in the Municipality of Bigaa, Province of Bulacan, to Marciano C. Rivera Elementary School","orig":"An Act Changing the Name of Santol I Elementary School in the Municipality of Bigaa, Province of Bulacan, to Marciano C. Rivera Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2522","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2522_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2251-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Santol I Elementary School in the Municipality of Bigaa, Province of Bulacan, is hereby changed to Marciano C. Rivera Elementary School."}},{"id":"PH-H2251-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2252"] = {"id":"PH-H2252","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2523_1959.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Province of Surigao","orig":"An Act Creating Certain Barrios in the Province of Surigao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2523","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2523_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2252-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Amontay, Macopa and Magtanghali in the Municipality of Anao-aon, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Amontay, Macopa and Magtangali, respectively."}},{"id":"PH-H2252-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Tawagan, Panaosawon, Cabogo, Unidad, Lactudan, Pagbahanan and Salimbabayog in the Municipality of Cagwait, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Tawagan, Panaosawon, Cabogo, Unidad, Lactudan, Palhi, Pagbahanan and Bitaugan West, respectively."}},{"id":"PH-H2252-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Cabawan in the Municipality of Dapa, Province of Surigao, is converted into a barrio of said municipality to be known as the barrio of Cabawa."}},{"id":"PH-H2252-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sitios of Tagbina, Port Lamon, Dugmanon, Sasa, Manambia, Biga-an, Maglambing and Talisay in the Municipality of Hintuan, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Tagbina, Port Lamon, Dugmanon, Sasa, Manambia, Biga-an, Maglambing and Talisay, respectively."}},{"id":"PH-H2252-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sitios of Bungan, Salvacion, Mandus and Sabang in the Municipality of Lingig, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Bungan, Salvacion, Mandus and Sabang, respectively."}},{"id":"PH-H2252-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sitios of San Pedro, Alipao, Matinao, Tapian, Mansayao, Binga, San Francisco, Cantugas and Mainit in the Municipality of Mainit, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of San Pedro, Alipao, Matinao, Tapian, Mansayao, Binga, San Francisco, Cantugas and Mainit, respectively."}},{"id":"PH-H2252-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sitios of Cabongbongan, Cajuyao, Sabang, Punta Bilar, Nabago, Togbongo, Cagutsan, Balibayon, Orok, Cagniog, Mabuhay, Mabua, Alang-alang, Auora and Baybay in the Municipality of Surigao, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Cabongbongan, Cajuyao, Sabang, Punta Bilar, Nabago, Togbongan, Cagutsan, Balibayon, Orok, Cagniog, Mabuhay, Mabua Alang-alang, Aurora and Baybay, respectively."}},{"id":"PH-H2252-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The sitios of Awasan Norte, Buanbuan, Cagbaoto, Unahan and Abaga in the Municipality of Tago, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Awasan Norte, Buanbuan, Cagbaoto, Unahan and San Roque, respectively."}},{"id":"PH-H2252-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The sitios of Rosario Tabontabon, Sotil and Carmen in the Municipality of Tandag, Province of Surigao, are converted into barrios of said municipality to be known as the barrios of Rosario, Tabontabon, Sotil and Carmen, respectively."}},{"id":"PH-H2252-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2253"] = {"id":"PH-H2253","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2524_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Malilipot市","en":"An Act Converting the Sitio of Calbayog, Municipality of Malilipot, Province of Albay, into a Barrio of Said Municipality","orig":"An Act Converting the Sitio of Calbayog, Municipality of Malilipot, Province of Albay, into a Barrio of Said Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2524","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2524_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2253-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Calbayog, Municipality of Malilipot, Province of Albay, is converted into a barrio of said municipality to be known as the barrio of Calbayog."}},{"id":"PH-H2253-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2254"] = {"id":"PH-H2254","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2525_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of Cuasi Elementary School in the Barrio of Tontonan, Municipality of Loon, Province of Bohol, to Tontonan Elementary School","orig":"An Act Changing the Name of Cuasi Elementary School in the Barrio of Tontonan, Municipality of Loon, Province of Bohol, to Tontonan Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2525","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2525_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2254-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Cuasi Elementary School in the barrio of Tontonan, Municipality of Loon, Province of Bohol, is changed to Tontonan Elementary School."}},{"id":"PH-H2254-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
  FT["PH-H2255"] = {"id":"PH-H2255","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2526_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Municipality of Payabon, Province of Negros Oriental, to Municipality of Bindoy","orig":"An Act Changing the Name of the Municipality of Payabon, Province of Negros Oriental, to Municipality of Bindoy"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2526","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2526_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2255-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"In order to honor the memory of one of the greatest statement produced by the Province of Negros Oriental, the name of the Municipality of Payabon, Province of Negros Oriental, is changed to Municipality of Bindoy."}},{"id":"PH-H2255-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p31"};
